--
-- Table structure for table `chat_offers`
--

DROP TABLE IF EXISTS `chat_offers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `chat_offers` (
  `id` int NOT NULL AUTO_INCREMENT,
  `conversation_id` int NOT NULL,
  `product_id` int DEFAULT NULL,
  `created_by_user_id` int NOT NULL,
  `created_by_role` enum('BUYER','SUPPLIER','SUPER_ADMIN') COLLATE utf8mb4_unicode_ci NOT NULL,
  `parent_offer_id` int DEFAULT NULL,
  `offer_version` int NOT NULL DEFAULT '1',
  `quantity` int NOT NULL,
  `unit` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pieces',
  `unit_price` decimal(12,2) NOT NULL,
  `currency` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INR',
  `total_amount` decimal(14,2) NOT NULL,
  `delivery_location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lead_time` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customization_terms` text COLLATE utf8mb4_unicode_ci,
  `additional_terms` text COLLATE utf8mb4_unicode_ci,
  `status` enum('DRAFT','PENDING_ACCEPTANCE','ACCEPTED','REJECTED','COUNTERED','WITHDRAWN','EXPIRED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_ACCEPTANCE',
  `expiry_date` date DEFAULT NULL,
  `accepted_by_user_id` int DEFAULT NULL,
  `accepted_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_offer_conv` (`conversation_id`),
  KEY `idx_offer_status` (`status`),
  KEY `idx_parent_offer` (`parent_offer_id`),
  CONSTRAINT `fk_chat_offers_conv` FOREIGN KEY (`conversation_id`) REFERENCES `chat_conversations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

