INSERT INTO `cms_pages` VALUES (1,'Why choose Sports Junction','why-choose-sports-junction','ABOUT','<h2>Why Choose Sports Junction</h2><p>Sports Junction is India\'s leading B2B marketplace dedicated to connecting worldwide buyers, sports brands, academies, and institutional buyers directly with audited and verified Indian sports manufacturers in Meerut, Jalandhar, and Gujarat.</p><ul><li>Direct factory wholesale pricing without trading intermediary markup.</li><li>Strict physical and compliance audits for all verified manufacturers.</li><li>Secure milestone-based negotiation and formal deal agreements.</li><li>Comprehensive export packaging, laboratory testing, and logistics coordination.</li></ul>',NULL,1,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(2,'Corporate responsibility','corporate-responsibility','ABOUT','<h2>Corporate Responsibility & Ethical Sourcing</h2><p>We are deeply committed to ethical manufacturing practices across India\'s sports equipment industry. Sports Junction strictly enforces zero child labour policies, equitable worker wages, safe working conditions, and environmentally sustainable production standards.</p>',NULL,2,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(3,'Careers','careers','ABOUT','<h2>Careers at Sports Junction</h2><p>Join our mission to revolutionize global sports supply chains and empower local Indian manufacturers on the international stage. We are hiring talented engineers, supply chain specialists, and relationship managers.</p><p>Send your resume to <strong>careers@sportsjunction.in</strong>.</p>',NULL,3,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(4,'Secure payments','secure-payments','ORDER_PROTECTION','<h2>Secure Payments & Buyer Protection</h2><p>Sports Junction provides end-to-end security for all wholesale business transactions. From encrypted digital communications to bank escrow and letter of credit (LC) support, your business funds remain protected at every stage.</p>',NULL,1,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(5,'Guaranteed delivery','guaranteed-delivery','ORDER_PROTECTION','<h2>Guaranteed On-Time Dispatch & Delivery</h2><p>Every formal negotiation on Sports Junction includes legally binding production lead times. If a verified manufacturer fails to meet the agreed dispatch milestones without mutual consent, buyers are eligible for penalty credits and prioritized expedited fulfillment.</p>',NULL,2,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(6,'Production monitoring & inspection services','inspection-services','ORDER_PROTECTION','<h2>Quality Inspection & Production Monitoring</h2><p>Our network of certified third-party QA inspectors conducts pre-production raw material testing, during-production batch checks, and pre-shipment container audits to ensure strict adherence to international sports standards.</p>',NULL,3,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(7,'Policies and rules','policies-and-rules','ORDER_PROTECTION','<h2>Platform Policies & Marketplace Guidelines</h2><p>Sports Junction maintains strict trading conduct. Direct off-platform payment diversion, counterfeit manufacturing, and deceptive specifications result in immediate vendor suspension and forfeiture of platform verification badges.</p>',NULL,4,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(8,'Verified manufacturers','verified-manufacturers','SOURCE','<h2>Verified Indian Manufacturers</h2><p>Explore audited manufacturing facilities with verified GST, IEC export licenses, and verified plant machinery in Meerut, Jalandhar, and Ahmedabad.</p>','/products?verified=1',1,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(9,'Request for Quotation','request-for-quotation','SOURCE','<h2>Request for Quotation (RFQ)</h2><p>Submit customized requirements including custom branding, export grade packaging, and target wholesale pricing to receive multiple verified quotes within 24 hours.</p>','/products',2,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(10,'Buyer Help Center','buyer-help-center','HELP_CENTER','<h2>Buyer Help Center & FAQs</h2><p>Find answers to common inquiries regarding buyer registration, requesting production samples, negotiating wholesale MOQs, and downloading export documentation.</p>',NULL,1,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(11,'Live chat','live-chat','HELP_CENTER','<h2>Real-Time Live Chat & Direct Negotiation</h2><p>Sports Junction features built-in real-time chat with instant document exchange and binding counter-offers. Open the chat widget at the bottom right of any product page to chat directly with verified factory representatives.</p>','/buyer/messages',2,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(12,'Sell on Sports Junction','sell-on-sports-junction','SELL','<h2>Sell on Sports Junction — Supplier Onboarding</h2><p>Expand your sports manufacturing factory to international importers in the USA, UK, Europe, Australia, and GCC. Register your factory and start receiving direct bulk purchase orders.</p>','/seller/login',1,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(13,'Become a Verified Supplier','become-verified-supplier','SELL','<h2>Become a Verified Sports Junction Manufacturer</h2><p>Undergo our comprehensive background verification and facility audit to earn the coveted Verified Supplier Badge, boosting your catalog visibility by over 300%.</p>','/seller/login',2,1,'2026-10-15 11:56:28','2026-10-15 11:56:28');
/*!40000 ALTER TABLE `cms_pages` ENABLE KEYS */;
UNLOCK TABLES;

