INSERT INTO `products` VALUES (1,1,3,5,'Grade-A English Willow Cricket Bat','grade-a-english-willow-cricket-bat','SJ-CRK-ENG01','Meerut Pro Series','Hand-crafted Grade 1 English Willow cricket bat with balanced pick up and thick edges.','Crafted from selected hand-split Grade 1 English willow grown in sustainable UK forests and seasoned in Meerut. Features massive contoured 40mm edges, balanced light pick up, semi-oval 12-piece cane handle with rubber grip, and toe guard protection.','https://images.unsplash.com/photo-1531415074868-036b1c57e329?auto=format&fit=crop&w=800&q=80',NULL,3800.00,4500.00,4500.00,1,25,1,500,1,4200.00,'Grade-1 English Willow, 12-Piece Cane Handle','Natural Wood, Black & Blue Grip','Full Size Short Handle (SH)','1160g - 1220g (2.9 - 2.11 lbs)',NULL,1,1,1,1,1,1,1,1,1,'10 - 20 Business Days','Ex-Factory Meerut or FOB Nhava Sheva Port, Mumbai','PUBLISHED','APPROVED',NULL,NULL,NULL,NULL,NULL,1,2,1,'2026-10-10 13:10:51','2026-10-13 13:27:02'),(2,2,4,7,'FIFA Quality Pro Synthetic Leather Football','fifa-quality-pro-synthetic-leather-football','SJ-BALL-FB02','Jalandhar Match Elite','Thermally bonded 32-panel FIFA standard size 5 football made with Japanese PU.','Engineered in Jalandhar leather & sports cluster. 32-panel aerodynamic design made with textured microfiber PU synthetic leather, 4-ply poly-cotton lining, high-rebound butyl bladder for maximum air retention and true flight precision.','https://images.unsplash.com/photo-1579952363873-27f3bade9f55?auto=format&fit=crop&w=800&q=80',NULL,720.00,850.00,850.00,1,100,1,2500,1,900.00,'Textured Microfiber Japanese PU, Butyl Bladder','White/Blue/Neon Red','Official Size 5','420g - 440g',NULL,1,1,1,1,1,1,1,2,4,'14 - 25 Business Days','FOB Mundra Port / CIF Worldwide Sea Freight','PUBLISHED','APPROVED',NULL,NULL,NULL,NULL,NULL,1,3,0,'2026-10-10 13:10:51','2026-10-10 14:29:32'),(3,1,6,3,'Adjustable Agility Training Hurdle (6\" to 12\")','adjustable-agility-training-hurdle','SJ-AGL-HD03','ApexSport Manufacturing','High-impact shatterproof PVC agility training hurdle with quick dual-height twist adjustment.','Engineered for high-intensity athletic conditioning, soccer drills, track and field, and functional rehabilitation. Built from ultra-durable shatterproof PVC tubing that bends and snaps back when stepped on. Features an ergonomic rotating base with secure locking pins for instant height switching between 6-inch and 12-inch elevations. Lightweight, easily nestable, and weather-resistant for indoor courts or outdoor turf.','https://images.unsplash.com/photo-1518611012118-696072aa579a?auto=format&fit=crop&w=800&q=80','https://www.youtube.com/watch?v=dQw4w9WgXcQ',280.00,380.00,320.00,1,50,1,12000,1,480.00,'High-Impact Shatterproof PVC & ABS Resin','Hi-Vis Fluorescent Green, Safety Orange, Electric Yellow','Width 45cm x Height 15cm-30cm (6\"-12\" Adjustable)','380g per unit','Silk-screen logo on horizontal crossbar, custom Pantone colors on orders > 500 units, customized carry bag with branded drawstrings.',1,1,1,1,1,1,1,1,1,'7 - 15 Business Days','Express air courier for samples (4-6 days), Sea freight LCL/FCL worldwide.','PUBLISHED','APPROVED',NULL,NULL,NULL,NULL,NULL,1,1,1441,'2026-10-10 14:29:32','2026-10-14 17:53:34'),(4,1,1,1,'Olympic Cast Iron Barbell Plates (Set of 100kg)','olympic-cast-iron-barbell-plates-set','SJ-GYM-PL04','ApexIron Foundry','High performance commercial sports equipment engineered for durability and athlete performance.','Precision manufactured at certified sports facilities in India. Built for commercial gyms, sports academies, clubs, and international distributors with full OEM & custom branding support.','https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=800&q=80',NULL,12500.00,14800.00,12500.00,1,10,1,5000,1,12500.00,'Precision Heavy Cast Iron with Hammertone Powder Coat','Multi-Color / Branded Pantone','Standard Competition','Commercial Grade',NULL,1,1,1,1,1,1,1,1,1,'12-20 Days','Standard B2B Global Freight','PUBLISHED','APPROVED',NULL,NULL,NULL,NULL,NULL,1,4,1,'2026-10-10 14:30:07','2026-10-10 15:27:52'),(5,1,6,3,'Speed Agility Footwork Ladder (6m Quick-Fold)','speed-agility-footwork-ladder-6m','SJ-AGL-LD05','ApexTrack Pro','High performance commercial sports equipment engineered for durability and athlete performance.','Precision manufactured at certified sports facilities in India. Built for commercial gyms, sports academies, clubs, and international distributors with full OEM & custom branding support.','https://images.unsplash.com/photo-1461896836934-ffe607ba8211?auto=format&fit=crop&w=800&q=80',NULL,240.00,310.00,240.00,1,100,1,5000,1,240.00,'Heavy-Duty PP Rungs & Reinforced Nylon Webbing','Multi-Color / Branded Pantone','Standard Competition','Commercial Grade',NULL,1,1,1,1,1,1,1,1,1,'12-20 Days','Standard B2B Global Freight','PUBLISHED','APPROVED',NULL,NULL,NULL,NULL,NULL,1,5,0,'2026-10-10 14:30:07','2026-10-10 14:30:07'),(6,1,6,4,'Saucer Field Cones with Metal Carrier (50-Pack)','saucer-field-cones-metal-carrier-50-pack','SJ-AGL-CN06','ApexSport Manufacturing','High performance commercial sports equipment engineered for durability and athlete performance.','Precision manufactured at certified sports facilities in India. Built for commercial gyms, sports academies, clubs, and international distributors with full OEM & custom branding support.','https://images.unsplash.com/photo-1517649763962-0c623266ddc0?auto=format&fit=crop&w=800&q=80',NULL,380.00,450.00,380.00,1,50,1,5000,1,380.00,'Flexible Low-Density Polyethylene (LDPE)','Multi-Color / Branded Pantone','Standard Competition','Commercial Grade',NULL,1,1,1,1,1,1,1,1,1,'12-20 Days','Standard B2B Global Freight','PUBLISHED','APPROVED',NULL,NULL,NULL,NULL,NULL,0,6,0,'2026-10-10 14:30:07','2026-10-10 14:30:07'),(7,1,1,1,'Test Pro Kettlebell Series 1791623641','test-pro-kettlebell-series-1791623641','TST-KB-99','ApexIron Test',NULL,NULL,'https://placehold.co/800x800?text=Kettlebell1',NULL,1450.00,1850.00,14